using UnityEngine;
using LWS.TruckSports;
namespace LWS.TruckMinefield {
public sealed class MinefieldRacer:MonoBehaviour {
 public MinefieldMatch match;public SportsEventTruck truck;public int slot;
 public MineAttempt Phase{get;private set;}public Vector3 LaunchOrigin{get;private set;}public Vector3 LastBlastOrigin{get;private set;}public Vector3 LandingOrigin{get;private set;}public float LaunchTime{get;private set;}public float LandingTime{get;private set;}public float FirstContactTime{get;private set;}=-1;public bool Retired{get;private set;}public int Distance{get;private set;}=-1;public int Launches{get;private set;}public int LandingLocks{get;private set;}public float CorrectionSpent=>correction;public float FinishTime{get;private set;}=float.PositiveInfinity;public bool TouchedSurface{get;private set;}public bool RecoveryLocked{get;private set;}public float QuietTime=>quiet;public bool OutsideFinalized{get;private set;}public Vector3 LastValidGroundedPosition=>lastValidGroundedPosition;public int CurrentDistance=>Distance>=0?Distance:MinefieldRules.Precision(float.IsFinite(truck.body.worldCenterOfMass.z)?truck.body.worldCenterOfMass.z:lastValidGroundedPosition.z);
 float stalled,flight,correction,quiet,lastSupport=-100,lastBlastAt=-100;bool airborne,neutral;float priorZ;Vector3 lastBlast,lastSupportedPosition,lastValidGroundedPosition;Collider supportingShape;
 public void ResetAttempt(Vector3 p,bool active){Phase=active?MineAttempt.Driving:MineAttempt.Failed;Distance=-1;Launches=LandingLocks=OutsideRecoveries=0;Retired=TouchedSurface=RecoveryLocked=OutsideFinalized=false;lastValidGroundedPosition=p;LandingTime=0;FirstContactTime=-1;FinishTime=float.PositiveInfinity;stalled=flight=correction=quiet=0;supportingShape=null;lastSupport=lastBlastAt=-100;airborne=neutral=false;truck.slot=slot;truck.visuals.gameObject.SetActive(active);if(active){truck.Prepare(p,Quaternion.identity);truck.Power(false);truck.body.isKinematic=true;priorZ=truck.body.worldCenterOfMass.z;}else truck.Park(p+Vector3.down*40);}
 public void Release(){if(Phase!=MineAttempt.Driving)return;truck.body.isKinematic=false;truck.Power(true);}
 public bool Launch(Vector3 blast){if(!match.Live||match.Phase!=MinefieldPhase.Driving||(Phase!=MineAttempt.Driving&&Phase!=MineAttempt.Launched))return false;if(match.HeatTime-lastBlastAt<.12f&&(blast-lastBlast).sqrMagnitude<1)return false;lastBlastAt=match.HeatTime;lastBlast=blast;bool first=Phase==MineAttempt.Driving;Phase=MineAttempt.Launched;Launches++;LastBlastOrigin=truck.body.worldCenterOfMass;if(first){LaunchOrigin=LastBlastOrigin;LaunchTime=match.HeatTime;}quiet=0;lastSupport=-100;truck.Power(false);var forward=Vector3.ProjectOnPlane(truck.transform.forward,Vector3.up).normalized;if(forward.z<.3f)forward=(forward+Vector3.forward*1.5f).normalized;var delta=forward*(26+Mathf.Clamp(truck.body.linearVelocity.magnitude*.35f,0,8))+Vector3.up*27;float gain=first?1:Mathf.Clamp01((95-truck.body.linearVelocity.magnitude)/35);truck.body.AddForce(delta*gain,ForceMode.VelocityChange);truck.body.AddTorque(new Vector3(2.5f,slot%2==0?1:-1,.8f)*gain,ForceMode.VelocityChange);match.Blast(this,blast);return true;}
 public void Step(Vector2 drive,float dt){if(Phase==MineAttempt.Driving){truck.grip=1.15f*match.weatherField.Grip;truck.TickDrive(drive);var center=truck.body.worldCenterOfMass;if(truck.Grounded&&match.ContainsGround(center))lastValidGroundedPosition=center;if(Mathf.Abs(center.x)<=55&&MinefieldRules.DrivenFinish(Phase,priorZ,center.z,out float fraction)){Phase=MineAttempt.DrivenFinish;FinishTime=match.HeatTime-dt+dt*fraction;truck.TickDrive(Vector2.zero);}priorZ=center.z;stalled=truck.body.linearVelocity.sqrMagnitude<.25f&&Mathf.Abs(drive.y)>.2f?stalled+dt:0;if(stalled>10||Mathf.Abs(center.x)>57||center.y< -15)Fail();return;}if(Phase!=MineAttempt.Launched)return;
  flight+=dt;if(!TouchedSurface){if(!neutral&&Mathf.Abs(drive.y)<.12f)neutral=true;var input=new Vector2(drive.x,neutral?drive.y:0);float spent=Mathf.Min(input.magnitude*dt,Mathf.Max(0,2.2f-correction));correction+=spent;float gain=input.magnitude>.001f?spent/(input.magnitude*dt):0;truck.body.AddForce(new Vector3(input.x*2.3f,0,input.y*1.8f)*gain,ForceMode.Acceleration);truck.body.AddTorque(new Vector3(input.y*.5f,0,-input.x*.5f)*gain,ForceMode.Acceleration);}
  airborne|=truck.body.worldCenterOfMass.y-match.GroundHeight(truck.body.position)>1.7f;bool supported=match.HeatTime-lastSupport<dt*2.5f;if(!supported&&truck.body.IsSleeping()&&TouchedSurface&&supportingShape!=null&&supportingShape.enabled&&supportingShape.gameObject.activeInHierarchy&&(truck.body.position-lastSupportedPosition).sqrMagnitude<.0025f)supported=true;
  bool slow=truck.body.linearVelocity.sqrMagnitude<.0625f&&truck.body.angularVelocity.sqrMagnitude<.1225f;quiet=supported&&slow?quiet+dt:0;if(quiet>=1.5f){LockRest(false);return;}
  var position=truck.body.position;bool finite=float.IsFinite(position.x)&&float.IsFinite(position.y)&&float.IsFinite(position.z);if(!finite||!match.ContainsGround(position)&&position.y< -40&&truck.body.linearVelocity.y<0){FinalizeOutsideWorld();return;}
  // A long flight or its zero-speed apex is never a settled landing. Persistent low-energy supported
  // simulation failure has a separate generous bound, and is explicitly identified in the result.
  if(flight>=180&&supported&&truck.body.linearVelocity.sqrMagnitude<2.25f&&truck.body.angularVelocity.sqrMagnitude<4)LockRest(true);
 }
 public int OutsideRecoveries{get;private set;}
 void FinalizeOutsideWorld(){OutsideRecoveries++;OutsideFinalized=true;RecoveryLocked=true;LockRest(true,lastValidGroundedPosition);Debug.Log("MINEFIELD_OUTSIDE_FINAL slot="+slot+" lastValidGround="+lastValidGroundedPosition+" distance="+Distance);}

 void LockRest(bool recovery,Vector3? validPosition=null){if(Phase!=MineAttempt.Launched)return;RecoveryLocked|=recovery;Phase=MineAttempt.Landed;LandingLocks++;LandingTime=match.HeatTime;LandingOrigin=validPosition??truck.body.worldCenterOfMass;Distance=MinefieldRules.Precision(RecoveryLocked&&!OutsideFinalized?Mathf.Min(LandingOrigin.z,LastBlastOrigin.z):LandingOrigin.z);truck.Power(false);truck.body.linearVelocity=truck.body.angularVelocity=Vector3.zero;truck.body.isKinematic=true;truck.body.detectCollisions=false;match.Landed(this);}
 void Retire(){if(Retired)return;Retired=true;truck.Power(false);truck.body.isKinematic=true;truck.body.detectCollisions=false;truck.visuals.gameObject.SetActive(false);}
 public void Fail(){if(Phase==MineAttempt.Landed||Phase==MineAttempt.Failed||Phase==MineAttempt.DrivenFinish)return;Phase=MineAttempt.Failed;LandingOrigin=lastValidGroundedPosition;Distance=MinefieldRules.Precision(lastValidGroundedPosition.z);Retire();}
 void Contact(Collision collision){if(!match.Live||(Phase!=MineAttempt.Launched&&Phase!=MineAttempt.Driving))return;bool ground=collision.collider is TerrainCollider||collision.rigidbody==null;bool support=false;if(ground)for(int i=0;i<collision.contactCount;i++)if(collision.GetContact(i).normal.y>.25f){support=true;break;}if(!support)return;if(match.ContainsGround(truck.body.position))lastValidGroundedPosition=truck.body.worldCenterOfMass;if(Phase!=MineAttempt.Launched||!airborne)return;lastSupport=match.HeatTime;supportingShape=collision.collider;lastSupportedPosition=truck.body.position;if(!TouchedSurface){TouchedSurface=true;FirstContactTime=match.HeatTime;}}
 void OnCollisionEnter(Collision collision){Contact(collision);}void OnCollisionStay(Collision collision){Contact(collision);}
}
}
